SELECT analytics_contract_facts.contract_risk, SUM(analytics_contract_facts.active_contract_value) AS active_contract_value FROM analytics_contract_facts WHERE analytics_contract_facts.year = 2022 AND analytics_contract_facts.month = 2 AND analytics_contract_facts.status = 'active' AND analytics_contract_facts.region = 'North' GROUP BY analytics_contract_facts.contract_risk ORDER BY active_contract_value DESC, analytics_contract_facts.contract_risk ASC LIMIT 10
